const data = JSON.parse(output);
const reqs = data.requirements;
if (!Array.isArray(reqs) || reqs.length === 0) return false;
// Validar campos obligatorios
const allHaveFields = reqs.every(r => r.code && r.name && r.type);
if (!allHaveFields) return false;
// Ausencia de códigos duplicados
const codes = reqs.map(r => r.code);
const uniqueCodes = new Set(codes);
return codes.length === uniqueCodes.size;

const data = JSON.parse(output);
const actors = data.actors;
if (!Array.isArray(actors) || actors.length === 0) return false;
const names = actors.map(a => a.name.toLowerCase());
// Debe contener al menos paciente o médico/doctor
const hasExpected = names.some(n => n.includes('médic') || n.includes('medic') || n.includes('paciente') || n.includes('doctor') || n.includes('usuario'));
return hasExpected;
